from test_bufftap import test,tests
setup="""
local B=BuffTap; context='solo'; active=1; groupCount=2
IsInRaid=function() return context=='raid' end
IsInGroup=function() return context~='solo' end
GetNumSubgroupMembers=function() return context=='solo' and 0 or 2 end
GetNumSpecGroups=function() return groupCount end
C_SpecializationInfo=C_SpecializationInfo or {}
C_SpecializationInfo.GetActiveSpecGroup=function() return active end
B:Refresh()
"""
on=setup+"assert(B:SetSpecEnabled(true)); "
def case(name,code):test(name,setup+code)
def cased(name,code):test(name,on+code)
case('One spec group reads as Spec 1 and Spec 2 can be prepared',"groupCount=1; assert(B:SpecGroup()==1 and B:SetSpecEnabled(true) and B:ActiveSpec()==1); B:SetEditSpec(2); assert(B:EditSpec()==2 and B:ActiveSpec()==1)")
case('Reader returns the active group',"assert(B:SpecGroup()==1); active=2; assert(B:SpecGroup()==2)")
for result in ["error('unavailable')","return {secret=true}","return nil","return 3","return 0"]:
 case('Reader safe when active group is '+result,"C_SpecializationInfo.GetActiveSpecGroup=function() "+result+" end; assert(B:SpecGroup()==nil)")
for result in ["error('unavailable')","return nil","return 'x'"]:
 case('Reader safe when group count is '+result,"GetNumSpecGroups=function() "+result+" end; assert(B:SpecGroup()==nil)")
case('Reader safe without the API',"GetNumSpecGroups=nil; assert(B:SpecGroup()==nil); GetNumSpecGroups=function() return 2 end; C_SpecializationInfo=nil; assert(B:SpecGroup()==nil)")
case('Switch is off by default and changes nothing',"assert(B.db.situationSettings.spec.enabled==false and not B:ActiveSpec() and B:Preference('buffs')==B.db.buffs and B:EditSpec()==nil)")
cased('Switch on reports active and edit spec',"assert(B:ActiveSpec()==1 and B:EditSpec()==1); B:SetEditSpec(2); assert(B:EditSpec()==2 and B:ActiveSpec()==1)")
cased('Active spec is read on every refresh without an event',"B:SetSpecValue(1,'buffs','buffs',false,'motw'); refresh(); assert(B.action.id==467); active=2; refresh(); assert(B.action.id==5232); active=1; refresh(); assert(B.action.id==467)")
cased('Spec layer applies in Party and Raid too',"B:SetSpecValue(1,'buffs','buffs',false,'motw'); for _,c in ipairs({'party','raid'}) do context=c; refresh(); assert(B.situationCurrent==c and B:Preference('buffs').motw==false) end; active=2; context='party'; refresh(); assert(B:Preference('buffs').motw~=false)")
cased('Spec layer sits on top of a situation override',"B:SetEditSpec(1); B.db.situationSettings.party.buffs={buffs={motw=false}}; B.db.situationSettings.spec[2]={buffs={buffs={motw=true}}}; active=2; context='party'; refresh(); assert(B:Preference('buffs').motw==true); B.db.situationSettings.spec[2].buffs.buffs.motw='default'; B:SituationChanged(); assert(B:Preference('buffs').motw==false)")
cased('Spec layer inherits later Solo changes',"B:SetSpecValue(1,'buffs','buffs',false,'motw'); B:SetEditSpec(2); B.db.buffs.thorns=false; B.situationDirty=true; refresh(); assert(B:Preference('buffs').motw==false and B:Preference('buffs').thorns==false)")
cased('Weapon choices and hands are per spec',"playerClass='SHAMAN'; B:InitDB(); B:SetSpecEnabled(true); B:SetSpecValue(1,'weapons','weaponChoices','flametongue','main'); B:SetSpecValue(2,'weapons','weaponChoices','windfury','main'); B:SetSpecValue(2,'weapons','weaponOffHand',false); assert(B:SituationPreview('solo','weapons',1).weaponChoices.main=='flametongue' and B:SituationPreview('solo','weapons',2).weaponChoices.main=='windfury' and B:SituationPreview('solo','weapons',2).weaponOffHand==false and B:SituationPreview('solo','weapons',1).weaponOffHand==B.db.weaponOffHand)")
cased('Consumable choices and timing are per spec',"local fam=B:ConsumableFamily('flask'); assert(fam); B:SetSpecValue(2,'consumables','consumableSeconds',600,'flask'); B:SetSpecValue(2,'consumables','consumablesEnabled',true); assert(B:SituationPreview('solo','consumables',2).consumableSeconds.flask==600 and B:SituationPreview('solo','consumables',1).consumableSeconds.flask==B.db.consumableSeconds.flask and B:SituationPreview('solo','consumables',2).consumablesEnabled==true)")
cased('Editor writes either-or buffs to the edited spec only',"playerClass='MAGE'; B:InitDB(); B:SetSpecEnabled(true); B:SetEditSpec(2); B:EditorSettings('buffs').buffs['ice-armor']=true; assert(B:SpecValues(2,'buffs').buffs['ice-armor']==true and not B:SpecValues(1,'buffs') and B.db.buffs['ice-armor']~=true)")
cased('Any buff row is per spec while timers stay shared',"playerClass='MAGE'; B:InitDB(); B:SetSpecEnabled(true); B:SetEditSpec(2); B:EditorSettings('buffs').buffs.ai=false; B:EditorSettings('buffs').seconds=90; assert(B:SpecValues(2,'buffs').buffs.ai==false and B.db.buffs.ai~=false and not B:SpecValues(2,'buffs').seconds and B.db.seconds==90)")
cased('Every class can set buffs per spec',"for _,c in ipairs({'DRUID','PALADIN','PRIEST','WARLOCK','HUNTER','WARRIOR','ROGUE','SHAMAN','MAGE'}) do playerClass=c; B:InitDB(); assert(B:SpecApplies('buffs') and B:SpecApplies('weapons') and B:SpecApplies('consumables'),c) end")
cased('Paladin blessing and Righteous Fury follow the spec',"playerClass='PALADIN'; B:InitDB(); B:SetSpecEnabled(true); B:SetEditSpec(2); B:EditorSettings('buffs').buffs['righteous-fury']=true; B:EditorSettings('buffs').buffs.bom=false; local v=B:SpecValues(2,'buffs').buffs; assert(v['righteous-fury']==true and v.bom==false and B.db.buffs['righteous-fury']~=true and B.db.buffs.bom~=false)")
cased('Editor reads show the edited spec',"playerClass='MAGE'; B:InitDB(); B:SetSpecEnabled(true); B:SetSpecValue(2,'buffs','buffs',true,'ice-armor'); B:SetEditSpec(2); assert(B:EditorSettings('buffs').buffs['ice-armor']==true); B:SetEditSpec(1); assert(B:EditorSettings('buffs').buffs['ice-armor']~=true)")
cased('Weapon page edits follow the edited spec',"playerClass='SHAMAN'; B:InitDB(); B:SetSpecEnabled(true); B:SetEditSpec(2); B:EditorSettings('weapons').weaponMainHand=false; assert(B:SpecValues(2,'weapons').weaponMainHand==false and B.db.weaponMainHand~=false)")
cased('Consumable page edits follow the edited spec for any class',"playerClass='PRIEST'; B:InitDB(); B:SetSpecEnabled(true); B:SetEditSpec(2); B:EditorSettings('consumables').consumablesEnabled=true; assert(B:SpecValues(2,'consumables').consumablesEnabled==true)")
case('Single-spec characters can prepare Spec 2 without it applying',"groupCount=1; playerClass='MAGE'; B:InitDB(); assert(B:SetSpecEnabled(true)); B:SetEditSpec(2); B:EditorSettings('buffs').buffs['ice-armor']=true; assert(B:SpecValues(2,'buffs').buffs['ice-armor']==true and B:Preference('buffs')['ice-armor']~=true); active=2; groupCount=2; B:SyncSituation(); assert(B:Preference('buffs')['ice-armor']==true)")
cased('Switch off keeps saved choices but stops applying them',"B:SetSpecValue(1,'buffs','buffs',false,'motw'); refresh(); assert(B.action.id==467); assert(B:SetSpecEnabled(false)); refresh(); assert(B.action.id==5232 and B:SpecValues(1,'buffs').buffs.motw==false); assert(B:SetSpecEnabled(true)); refresh(); assert(B.action.id==467)")
cased('Switch off sends edits back to the situation settings',"B:SetSpecEnabled(false); B:SetSituationValue('party','buffs','seconds',90); assert(B:SituationValues('party','buffs').seconds==90 and not B:SpecValues(1,'buffs'))")
cased('Losing the second spec group falls back to Spec 1',"B:SetSpecValue(2,'buffs','buffs',false,'motw'); active=2; refresh(); assert(B.action.id==467); groupCount=1; refresh(); assert(B.action.id==5232 and B:ActiveSpec()==1); B:SetSpecValue(1,'buffs','buffs',false,'motw'); refresh(); assert(B.action.id==467)")
cased('Saved spec choices survive a reload',"B:SetSpecValue(2,'buffs','seconds',77); B:InitDB(); assert(B.db.situationSettings.spec.enabled==true and B:SpecValues(2,'buffs').seconds==77)")
case('Invalid saved spec data is cleaned',"B.db.situationSettings.spec={enabled='yes',[1]={buffs={buffs={motw='bad',nonsense=true},seconds=9999},junk=1},[3]={buffs={seconds=60}}}; B:InitDB(); local s=B.db.situationSettings.spec; assert(s.enabled==false and s[3]==nil and s[1].buffs.seconds==180 and s[1].buffs.buffs==nil and s[1].junk==nil)")
case('Spec edits refused for bad input',"assert(B:SetSpecEnabled(true)); assert(not B:SetSpecValue(3,'buffs','seconds',60) and not B:SetSpecValue(1,'buffs','weaponSeconds',60) and not B:SetSpecValue(1,'buffs','seconds',60,'x'))")
cased('Spec writes refused during combat',"combat=true; assert(not B:SetSpecValue(1,'buffs','seconds',60) and not B:SetSpecEnabled(false)); combat=false")
cased('Spec flip in combat waits until combat ends',"B:SetSpecValue(1,'buffs','buffs',false,'motw'); refresh(); assert(B.action.id==467); combat=true; active=2; B:SyncSituation(); assert(B.situationDeferred and B.specCurrent==1); combat=false; refresh(); assert(B.specCurrent==2 and B.action.id==5232)")
cased('Shared profile switch keeps spec choices',"B:SetSpecValue(1,'buffs','seconds',77); B:CreateSettingsProfile('Other',false); assert(B:SpecValues(1,'buffs').seconds==77)")
cased('Unreadable group mid-switch drops the layer then recovers',"B:SetSpecValue(1,'buffs','buffs',false,'motw'); refresh(); assert(B.action.id==467); C_SpecializationInfo.GetActiveSpecGroup=function() error('busy') end; refresh(); assert(B.action.id==5232); C_SpecializationInfo.GetActiveSpecGroup=function() return 1 end; refresh(); assert(B.action.id==467)")

import test_bufftap
from test_bufftap import ROOT
RECORD=(ROOT/'tests/nearby_preview_record.lua').read_text(encoding='utf-8-sig')
ui=RECORD+setup+"""
local function pos(o) local p=o.__draw.points[1]; return p[2],p[3] end
local function bar(cat) return B.contextControls[cat] end
"""
def uicase(name,code):test(name,ui+code)
uicase('Bar shows for single-spec characters so Spec 2 can be prepared',"groupCount=1; playerClass='SHAMAN'; B:InitDB(); B:Options(); for _,c in ipairs({'buffs','weapons','consumables'}) do assert(bar(c).specCheck.shown) end; local c=bar('weapons').specCheck; c:SetChecked(true); c.scripts.OnClick(c); assert(B:SpecEnabled() and bar('buffs').specButtons[1].shown); assert(bar('buffs').specButtons[1].activeDot.shown and not bar('buffs').specButtons[2].activeDot.shown)")
uicase('Bar shows the switch and hides the spec pills while off',"playerClass='SHAMAN'; B:InitDB(); B:Options(); for _,c in ipairs({'buffs','weapons','consumables'}) do assert(bar(c).specCheck.shown and not bar(c).specButtons[1].shown and not bar(c).specLabel.shown) end")
uicase('Switch click enables and shows the pills on every page',"playerClass='SHAMAN'; B:InitDB(); B:Options(); local c=bar('weapons').specCheck; c:SetChecked(true); c.scripts.OnClick(c); assert(B:SpecEnabled()); for _,n in ipairs({'buffs','weapons','consumables'}) do assert(bar(n).specButtons[1].shown and bar(n).specButtons[2].shown and bar(n).specLabel.shown and bar(n).specCheck:GetChecked()) end")
uicase('Spec pill changes the edited spec for all pages',"playerClass='SHAMAN'; B:InitDB(); B:SetSpecEnabled(true); B:Options(); bar('consumables').specButtons[2].scripts.OnClick(); assert(B:EditSpec()==2 and B:ActiveSpec()==1); assert(bar('buffs').status:GetText():find('Spec 2'))")
uicase('Green dot marks the active spec',"playerClass='SHAMAN'; B:InitDB(); B:SetSpecEnabled(true); B:Options(); assert(bar('buffs').specButtons[1].activeDot.shown and not bar('buffs').specButtons[2].activeDot.shown); active=2; B:UpdateContextControls(); assert(bar('buffs').specButtons[2].activeDot.shown and not bar('buffs').specButtons[1].activeDot.shown)")
uicase('Priest sees the bar on every page',"playerClass='PRIEST'; B:InitDB(); B:Options(); assert(bar('consumables').specCheck.shown and bar('weapons').specCheck.shown and bar('buffs').specCheck.shown)")
cased('Weapon oils and stones are per spec for a Druid',"playerClass='DRUID'; B:InitDB(); B:SetSpecEnabled(true); assert(B:SpecApplies('weapons') and B:SpecApplies('consumables') and B:SpecApplies('buffs')); B:SetEditSpec(2); B:EditorSettings('weapons').weaponMainHand=false; assert(B:SpecValues(2,'weapons').weaponMainHand==false and B.db.weaponMainHand~=false)")
uicase('Rogue sees the bar on Weapons and Consumables',"playerClass='ROGUE'; B:InitDB(); B:Options(); assert(bar('weapons').specCheck.shown and bar('consumables').specCheck.shown)")
uicase('Bar rows sit under the pills and clear the page content',"playerClass='SHAMAN'; B:InitDB(); B:SetSpecEnabled(true); B:Options(); local f=B.options; for _,n in ipairs({'buffs','weapons','consumables'}) do local x,y=pos(bar(n).specCheck); assert(x==18 and y==-36); x,y=pos(bar(n).specButtons[1]); assert(x==540 and y==-38); x,y=pos(bar(n).specButtons[2]); assert(x==622 and y==-38 and x+78<=700) end; local _,wy=pos(f.weaponContent); assert(wy==-20); local _,cy=pos(f.consumableBody); assert(cy==-20); local _,hy=pos(f.buffRebuffHeader); assert(hy<=-70)")
uicase('Page content steps down for single-spec characters too',"groupCount=1; playerClass='SHAMAN'; B:InitDB(); B:Options(); local f=B.options; local _,wy=pos(f.weaponContent); local _,cy=pos(f.consumableBody); assert(wy==-20 and cy==-20)")
uicase('Page content steps down for the switch row even when off',"playerClass='SHAMAN'; B:InitDB(); B:Options(); local f=B.options; local _,wy=pos(f.weaponContent); local _,cy=pos(f.consumableBody); assert(wy==-20 and cy==-20)")
uicase('Moved Consumables footer still ends above the footer',"playerClass='SHAMAN'; B:InitDB(); B:SetSpecEnabled(true); B:Options(); local n=#B.ConsumableVisibleFamilies; local retryY=-120-n*92+8-48-20; assert(-retryY+26<=664,'Retry reminders button reaches the footer: '..tostring(-retryY+26))")
uicase('Weapons status line stays on the page with the bar',"playerClass='SHAMAN'; B:InitDB(); B:SetSpecEnabled(true); B:Options(); local _,y=pos(B.options.weaponStatus); assert(-y+20+16<=664,tostring(y))")
for loc in ['deDE','esES','frFR','ptBR']:
 txt=open(str(ROOT/('addon/BuffTap/Locales/'+loc+'.lua')),encoding='utf-8').read()
 for key in ['Different settings per spec','Editing','Spec 1','Spec 2','Editing Spec %d. Used in every setup.','Spec %d','Differs from Spec %d','Keep separate choices for your two specs. Which buffs, weapon buffs and consumables to keep up, and their weapon and consumable timers, follow the spec you are in. Buff timers and everything else are shared. You can set up Spec 2 before you learn dual spec.','Choose which spec you are editing. The green dot marks the spec you are in now.']:
  assert 'B.Locales.'+loc+'["'+key+'"]=' in txt,(loc,key)
uicase('Either-or buff rows always carry a Spec tag, other rows only when specs differ',"playerClass='MAGE'; B:InitDB(); B:SetSpecEnabled(true); B:Options(); local tagged,plain; for _,row in ipairs(B.options.buffRows) do if row.def and row.shown~=false then local t=row.name:GetText() or ''; if row.def.key=='ice-armor' then tagged=t elseif row.def.key=='ai' then plain=t end end end; assert(tagged and tagged:find('Spec 1'),tostring(tagged)); assert(plain and not plain:find('Spec'),tostring(plain)); B:SetEditSpec(2); B:EditorSettings('buffs').buffs.ai=false; B:Options(); for _,row in ipairs(B.options.buffRows) do if row.def and row.def.key=='ai' then plain=row.name:GetText() or '' end end; assert(plain:find('Differs from Spec 1'),plain)")
uicase('No Spec tags while the switch is off',"playerClass='MAGE'; B:InitDB(); B:Options(); for _,row in ipairs(B.options.buffRows) do local t=row.name:GetText() or ''; assert(not t:find('Spec %d'),t) end")
uicase('Consumable rows say when the other spec differs',"playerClass='PRIEST'; B:InitDB(); B:SetSpecEnabled(true); B:SetSpecValue(2,'consumables','consumableSeconds',600,'flask'); B:SetEditSpec(2); B:Options(); local flask,food; for _,row in ipairs(B.options.consumableRows) do if row.family.key=='flask' then flask=row.name:GetText() elseif row.family.key=='food' then food=row.name:GetText() end end; assert(flask and flask:find('Differs from Spec 1'),tostring(flask)); assert(not (food or ''):find('Differs'),tostring(food))")
uicase('Spec bar controls are exempt from the card inset',"playerClass='SHAMAN'; B:InitDB(); B:Options(); for _,n in ipairs({'buffs','weapons','consumables'}) do assert(bar(n).specCheck.visualInsetX==18 and bar(n).specButtons[1].visualInsetX==540 and bar(n).specButtons[2].visualInsetX==622) end")
uicase('Bar sits correctly on My buffs for Paladin',"playerClass='PALADIN'; B:InitDB(); B:SetSpecEnabled(true); B:Options(); local x,y=pos(bar('buffs').specCheck); assert(bar('buffs').specCheck.shown and x==18 and y==-36); x,y=pos(bar('buffs').specButtons[2]); assert(x==622 and y==-38); local _,hy=pos(B.options.buffRebuffHeader); assert(hy<=-70)")
uicase('Bar sits correctly on My buffs for Hunter',"playerClass='HUNTER'; B:InitDB(); B:SetSpecEnabled(true); B:Options(); local x,y=pos(bar('buffs').specCheck); assert(bar('buffs').specCheck.shown and x==18 and y==-36); x,y=pos(bar('buffs').specButtons[2]); assert(x==622 and y==-38); local _,hy=pos(B.options.buffRebuffHeader); assert(hy<=-70)")
uicase('Bar sits correctly on My buffs for Priest',"playerClass='PRIEST'; B:InitDB(); B:SetSpecEnabled(true); B:Options(); local x,y=pos(bar('buffs').specCheck); assert(bar('buffs').specCheck.shown and x==18 and y==-36); x,y=pos(bar('buffs').specButtons[2]); assert(x==622 and y==-38); local _,hy=pos(B.options.buffRebuffHeader); assert(hy<=-70)")
cased('Shield charge refresh follows the spec',"playerClass='SHAMAN'; B:InitDB(); B:SetSpecEnabled(true); B:SetEditSpec(2); B:EditorSettings('buffs').buffCharges['lightning-shield']=1; assert(B:SituationPreview('solo','buffs',2).buffCharges['lightning-shield']==1 and (B:SituationPreview('solo','buffs',1).buffCharges['lightning-shield'] or 0)==0 and (B.db.buffCharges['lightning-shield'] or 0)==0)")
